namespace ghidra.app.plugin.core.debug.gui.control;



using docking;
using docking.action;
using docking.menu;
using docking.menu;
using docking.widgets;
using ghidra.app.plugin.core.debug.gui;
using ghidra.debug.api.control;
using ghidra.util;

class ControlModeAction : MultiStateDockingAction<ControlMode> {
	public static readonly string NAME = "Control Mode";
	public static readonly string DESCRIPTION = "Choose what to control and edit in dynamic views";
	public static readonly string GROUP = DebuggerResources.GROUP_CONTROL;
	public static readonly string HELP_ANCHOR = "control_mode";

	private DebuggerControlPlugin plugin;

	public ControlModeAction(DebuggerControlPlugin plugin) : base(NAME, plugin.getName())
    {
		this.plugin = plugin;
		setDescription(DESCRIPTION);
		setToolBarData(new ToolBarData(DebuggerResources.ICON_BLANK, GROUP, ""));
		setHelpLocation(new HelpLocation(getOwner(), HELP_ANCHOR));
		setActionStates(ControlMode.ALL.stream()
				.map(m => new(m.name, m.icon, m))
				.collect(Collectors.toList()));
		setEnabled(false);
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		return plugin.current.getTrace() != null;
	}

	/* @Override */
	protected bool isStateEnabled(ActionState<ControlMode> state) {
		return state.getUserData().isSelectable(plugin.current);
	}

	/* @Override */
	public void actionStateChanged(ActionState<ControlMode> newActionState,
			EventTrigger trigger) {
		plugin.activateControlMode(newActionState, trigger);
	}
}
